#include <WiFi.h>
#include <HTTPClient.h>

void setup() {
  Serial.begin(115200);
  WiFi.begin("{{ssid}}", "{{password}}");
  while (WiFi.status() != WL_CONNECTED) delay(300);
  HTTPClient http;
  http.begin("{{url}}");
  int code = http.GET();
  if (code > 0) Serial.println(http.getString());
  http.end();
}

void loop() {}
